79	    /** Add a period from and to a date, inclusive, capping each person's OPEN and PENDING claims in
80	     *  it (null: no cap). Refused when the cap is below 1, when another period on the sheet has the
81	     *  name, the from-date is after the to-date, or it shares a day with another period. The sheet
82	     *  is held locked so periods added at the same moment are checked against each other. */
83	    @Transactional
84	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
85	        sheets.lock(sheetId);
86	        if (cap != null && cap < 1) {
87	            throw new PeriodRefusedException("The period's cap is not a whole number of at least 1");
88	        }
89	        if (from.isAfter(to)) {
90	            throw new PeriodRefusedException("The period's from-date is after its to-date");
91	        }
92	        if (periods.nameInUse(sheetId, name)) {
93	            throw new PeriodRefusedException("The name " + name + " is already in use on the sheet");
94	        }
95	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
96	            throw new PeriodRefusedException("The period overlaps another on the sheet");
97	        }
98	        Period saved = save(new Period(sheetId, name, from, to, cap));
99	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + name
100	                + " from=" + from + " to=" + to + (cap != null ? " cap=" + cap : ""));
101	        return saved;
102	    }
