130	     *  period, or whose days overlap a period on the sheet, is left out and the others are still made.
131	     *  Returns how many were made. */
132	    @Transactional
133	    public int generateQuarters(String sheetId, String user, int year) {
134	        sheets.lock(sheetId);
135	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
136	        int made = 0;
137	        for (int quarter = 1; quarter <= 4; quarter++) {
138	            YearMonth first = YearMonth.of(year, quarter * 3 - 2);
139	            String name = String.format("%04d-Q%d", year, quarter);
140	            if (addUnlessTaken(sheetId, user, existing, name, first.atDay(1), first.plusMonths(2).atEndOfMonth())) {
141	                made++;
142	            }
143	        }
144	        return made;
145	    }
