252	        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
253	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
254	            Person person = byId.get(claim.getPersonId());
255	            if (person == null
256	                    || !claim.countsAsOf(atEnd.get(claim.getId()), person.getRetiredFrom(), today)
257	                    || !period.contains(claim.getDueBy())) {
258	                continue;
259	            }
260	            BigDecimal due = claimService.dueOf(sheetId, person, claim);
261	            if (due != null) {
