269	     *  shown now on their claims whose due-by falls in a period ending before this one starts, that
270	     *  were still OPEN or PENDING at the end of this period's last day (by the status each had then, as
271	     *  its status log records it) and the live rules leave in (a claim with no figure adds nothing), and
272	     *  their opening balance for it. */
273	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
274	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
275	                .collect(Collectors.toMap(Person::getId, Function.identity()));
276	        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
277	        LocalDate today = sheets.today(sheetId);
278	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
279	        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
280	        period.getPersonOpenings().forEach((id, amount) -> carried.computeIfPresent(id, (key, sum) -> sum.add(amount)));
281	        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
282	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
283	            Person person = byId.get(claim.getPersonId());
284	            ClaimStatus then = atEnd.get(claim.getId());
285	            if (person == null || then == null || !then.isOpen()
286	                    || !claim.countsAsOf(then, person.getRetiredFrom(), today)
287	                    || all.stream().noneMatch(own -> own.contains(claim.getDueBy())
288	                            && own.getTo().isBefore(period.getFrom()))) {
289	                continue;
290	            }
291	            BigDecimal due = claimService.dueOf(sheetId, person, claim);
292	            if (due != null) {
293	                carried.merge(person.getId(), due, BigDecimal::add);
